class FEManager {
public:
    void* IGO;
    void* pms;
    GraphicalMenuSystem* gms;
    FEEntityManager* em;
    void DrawFE();
};

void FEManager::DrawFE()
{
    nglListBeginScene();
    nglSetClearFlags(NGLCLEAR_Z | NGLCLEAR_COLOR | NGLCLEAR_STENCIL);
    gms->DrawMovie();
    nglListEndScene();

    nglListBeginScene();
    nglSetClearFlags(NGLCLEAR_Z | NGLCLEAR_STENCIL);
    em->DrawBack();
    gms->UpdateInScene();
    nglListEndScene();

    nglListBeginScene();
    nglSetClearFlags(NGLCLEAR_Z | NGLCLEAR_STENCIL);
    gms->Draw();
    nglListEndScene();

    nglListBeginScene();
    nglSetClearFlags(NGLCLEAR_Z | NGLCLEAR_STENCIL);
    em->DrawFront();
    nglListEndScene();

    nglListBeginScene();
    nglSetClearFlags(NGLCLEAR_Z | NGLCLEAR_STENCIL);
    gms->DrawTop();
    nglListEndScene();
}
